def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    opp_def = sum(1 for a in opp if a == 'D')
    me_def = sum(1 for a in me if a == 'D')
    opp_c = n - opp_def
    last_me, last_opp = history[-1]

    # Endgame: squeeze final rounds against non-punishing opponents.
    if n >= 97:
        return 'D'

    # Early: mirror with slight punishment.
    if n < 3:
        if last_opp == 'D':
            return 'D'
        return 'C'

    # Count recent opponent defections.
    rw = 8 if n >= 8 else n
    recent_opp = opp[-rw:]
    recent_def = sum(1 for a in recent_opp if a == 'D')
    recent_me = me[-rw:]
    recent_me_def = sum(1 for a in recent_me if a == 'D')

    # Detect opponent response to our last move (mimicry signals).
    # If opponent mostly mirrors us, cooperate to keep mutual CC.
    mimic = 0
    for i in range(1, n):
        if opp[i] == me[i - 1]:
            mimic += 1
    mimic_rate = mimic / float(n - 1)

    # Against near-pure cooperator: exploit with occasional cooperation.
    if opp_def == 0:
        # Pure cooperator so far. Defect frequently but not always in case
        # they can turn; with no noise this is a clean +2/round.
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Against near-pure defector: defect, with rare probes.
    if opp_c <= 1 and n >= 6:
        if rng.random() < 0.05:
            return 'C'
        return 'D'

    # Strong mimicry -> tit-for-tat is stable; defect once at the end only.
    if mimic_rate >= 0.7 and n >= 6:
        if last_opp == 'D':
            # Retaliate once, then forgive on the next round.
            if last_me == 'D':
                return 'C'
            return 'D'
        return 'C'

    # If opponent is heavily defecting, protect ourselves.
    if recent_def * 2 >= rw and recent_def >= 3:
        # Try a single cooperative bid to reset if their recent pattern
        # suggests they punish our defections.
        if last_me == 'D' and last_opp == 'C':
            return 'C'
        if recent_def >= rw - 1:
            return 'D'
        if rng.random() < 0.15:
            return 'C'
        return 'D'

    # Opponent overall moderate. Use generous tit-for-tat with a
    # willingness to exploit when they are passive.
    opp_rate = opp_def / float(n)

    if last_opp == 'D':
        # Punish but forgive quickly if history is mostly cooperative.
        if opp_rate < 0.3:
            if rng.random() < 0.5:
                return 'C'
            return 'D'
        if rng.random() < 0.2:
            return 'C'
        return 'D'

    # Opponent cooperated last.
    if opp_rate < 0.15 and n >= 12:
        # Very passive opponent: exploit while sprinkling cooperation.
        if rng.random() < 0.8:
            return 'D'
        return 'C'
    if opp_rate < 0.35 and n >= 10:
        if rng.random() < 0.35:
            return 'D'
        return 'C'
    return 'C'
